/* Project Scenes:
scene 0: home screen
scene 1: Intro cat
scene 2: climb cat tree
scene 3: cuddle on couch
scene 4: eat breakfast
scene 5: play with yarn ball
scene 6: nap
scene 7: end screen
*/

// project initialization
let questionOne = ["Climb the cat tree", "Eat breakfast"]
let questionTwo = ["Cuddle on the couch", "Eat breakfast"]
let questionThree = ["Play with a yarn ball", "Eat breakfast"]
let questionFour = ["Climb the cat tree", "Take a nap"]
let questionFive = ["Eat breakfast", "Take a nap"]

function callScene(sceneNum: number) {
    if (sceneNum == 0) {
        scene.setBackgroundImage(assets.image`homeScreen`)
        let title = sprites.create(assets.image`titleTextImage`, SpriteKind.Player)
        let directions = textsprite.create("Press any key to begin!", 1, 8)
        directions.setMaxFontHeight(8)
        directions.setPosition(screen.width / 2, 100)
        controller.pauseUntilAnyButtonIsPressed()
        sprites.destroy(title)
        sprites.destroy(directions)
        callScene(1)
    } else if (sceneNum == 1) {
        scene.setBackgroundImage(assets.image`scene1Screen`)
        story.printDialog("Meet my cat Whiskers. It's time for Whiskers to wake up! What should Whiskers do first?", screen.width / 2, 95, 50, 150, 1, 0)
        story.showPlayerChoices(questionOne[0], questionOne[1])
        if (story.checkLastAnswer(questionOne[0])) {

        } else if (story.checkLastAnswer(questionOne[1])) {

        }
    } else if (sceneNum == 2) {
        scene.setBackgroundImage(assets.image`scene2Screen`)
        story.printDialog("Whiskers loves to explore his cat tree! What should he do next?", 55, 100, 70, 100, 1, 6)
        story.showPlayerChoices(questionTwo[0], questionTwo[1])
        if (story.checkLastAnswer(questionTwo[0])) {

        } else if (story.checkLastAnswer(questionTwo[1])) {

        }
    } else if (sceneNum == 3) {
        scene.setBackgroundImage(assets.image`scene3Screen`)
        story.printDialog("Whiskers loves to snuggle up with his humans on the couch! What should he do now?", 90, 130, 70, 150, 1, 0)
        story.showPlayerChoices(questionThree[0], questionThree[1])
        if (story.checkLastAnswer(questionThree[0])) {
            callScene(5)
        } else if (story.checkLastAnswer(questionThree[1])) {
            callScene(4)
        }
    } else if (sceneNum == 4) {
        scene.setBackgroundImage(assets.image`scene4Screen`)
        story.printDialog("Breakfast time - yum!!", 50, 100, 80, 150, 1, 3)
        story.printDialog("What should Whiskers do after he finishes eating?", 50, 100, 80, 150, 1, 3)
        story.showPlayerChoices(questionFour[0], questionFour[1])
        if (story.checkLastAnswer(questionFour[0])) {
            callScene(2)
        } else if (story.checkLastAnswer(questionFour[1])) {
            callScene(6)
        }
    } else if (sceneNum == 5) {
        scene.setBackgroundImage(assets.image`scene5Screen`)
        story.printDialog("Whiskers can spend all day unraveling a ball of yarn! What should he do next?", 80, 115, 80, 150, 1, 8)
        story.showPlayerChoices(questionFive[0], questionFive[1])
        if (story.checkLastAnswer(questionFive[0])) {

        } else if (story.checkLastAnswer(questionFive[1])) {

        }
    } else if (sceneNum == 6) {
        scene.setBackgroundImage(assets.image`scene6Screen`)
        story.printDialog("Whiskers has had an exhausting morning! Time for a nap!", 90, 40, 50, 150, 1, 3)
        callScene(7)
    } else if (sceneNum == 7) {
        scene.setBackgroundImage(assets.image`endScreen`)
        let title = sprites.create(assets.image`endScreenText`, SpriteKind.Player)
        story.printDialog("Thanks for joining Whiskers on his morning activities!", screen.width / 2, 110, 50, 150, 1, 0)
        music.play(music.melodyPlayable(music.magicWand), music.PlaybackMode.UntilDone)
        game.reset()
    }
}

// project start
callScene(0)
